-- Integration tests only. Use an EMPTY database named unimatrix_feature_test.
CREATE TABLE faculty (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, faculty_name VARCHAR(100) NOT NULL, department VARCHAR(50) NOT NULL) ENGINE=InnoDB;
CREATE TABLE rooms (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, room_name VARCHAR(50) NOT NULL, building VARCHAR(50) NOT NULL, capacity INT NOT NULL) ENGINE=InnoDB;
CREATE TABLE courses (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, course_code VARCHAR(20) NOT NULL, course_title VARCHAR(100) NOT NULL, duration_hours FLOAT NOT NULL) ENGINE=InnoDB;
CREATE TABLE block_sections (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, section_name VARCHAR(50) NOT NULL, student_count INT NOT NULL) ENGINE=InnoDB;
CREATE TABLE schedule_folders (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, parent_id INT NULL, name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(parent_id) REFERENCES schedule_folders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE schedule_files (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, folder_id INT NULL, name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(folder_id) REFERENCES schedule_folders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE exam_schedules (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, course_id INT NULL, room_id INT NULL, block_section_id INT NULL, faculty_id INT NULL, exam_date DATE NULL, time_slot VARCHAR(50) NULL, schedule_id INT NULL, FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(room_id) REFERENCES rooms(id), FOREIGN KEY(block_section_id) REFERENCES block_sections(id), FOREIGN KEY(faculty_id) REFERENCES faculty(id), FOREIGN KEY(schedule_id) REFERENCES schedule_files(id) ON DELETE CASCADE) ENGINE=InnoDB;
